/// <summary>
/// This is an extension class for VendEditInvoice form MetPerformMatching control.
/// </summary>
[ExtensionOf(formControlStr(VendEditInvoice, MetPerformMatching))]
final class METVendEditInvoicePerformMatchingCtrl_Extension
{
}

Method.Source:
/// <summary>
/// Reset the custom match status on the vendor invoice form.
/// </summary>
public void clicked()
{
    next clicked();

    if (METVendParameters::find().EnableMetcashMatchingLogic)
    {
        FormControl performMatching = this;
        FormDataSource vendInvInfoTableDS = performMatching.formRun().dataSource(formDataSourceStr(VendEditInvoice, VendInvoiceInfoTable));
        VendInvoiceInfoTable vendInvoiceInfoTableLocal = vendInvInfoTableDS.cursor();
        FormRun vendEditInvoice_FormRun = performMatching.formRun();
        PurchFormLetter_Invoice purchFormLetter_Invoice =  vendEditInvoice_FormRun.metGetPurchFormLetter();

        PurchSelectLinesManager purchSelectLinesManager = PurchSelectLinesManager::newPurchSelectLinesManager(vendInvoiceInfoTableLocal.TableRefId);
        purchSelectLinesManager.parmParmId(vendInvoiceInfoTableLocal.ParmId);
        purchSelectLinesManager.metInitPurchSets();

        purchSelectLinesManager.passSets(purchFormLetter_Invoice);

        if (!vendInvoiceInfoTableLocal.skipCustomInvoiceMatching() && !vendInvoiceInfoTableLocal.isLandedCostEnabled())
        {
            vendInvInfoTableDS.executeQuery();
        }
    }
}
